--
-- Estructura de tabla para la tabla `despachos_arduino`
--

CREATE TABLE `despachos_arduino` (
  `id_despacho` int(11) NOT NULL,
  `id_comanda` int(11) NOT NULL COMMENT 'Referencia a la venta',
  `id_producto` int(11) NOT NULL COMMENT 'ID del producto',
  `sku` varchar(50) DEFAULT NULL COMMENT 'SKU del producto',
  `cantidad` int(11) NOT NULL COMMENT 'Cantidad a despachar',
  `ubicacion` varchar(2) NOT NULL COMMENT 'Ubicación en máquina (ej: A1, B2)',
  `id_pago` text NOT NULL COMMENT 'Referencia del pago aprobado',
  `estatus_despacho` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0=Pendiente, 1=Enviado al Arduino, 2=Despachado, 3=Error',
  `fecha_registro` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'Fecha de registro',
  `fecha_enviado` datetime DEFAULT NULL COMMENT 'Fecha de envío al Arduino',
  `fecha_despachado` datetime DEFAULT NULL COMMENT 'Fecha de despacho confirmado',
  `respuesta_arduino` text DEFAULT NULL COMMENT 'Respuesta del Arduino',
  `intentos_envio` int(11) NOT NULL DEFAULT 0 COMMENT 'Número de intentos de envío',
  `notas` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='Registro de despachos al Arduino';

