--
-- Estructura de tabla para la tabla `sincronizacion_log`
--

CREATE TABLE `sincronizacion_log` (
  `id_sync` int(11) NOT NULL,
  `tabla` varchar(100) NOT NULL COMMENT 'Nombre de la tabla sincronizada',
  `accion` varchar(50) NOT NULL COMMENT 'Tipo de acci??n: insert, update, delete, cierre_automatico',
  `id_registro` int(11) NOT NULL COMMENT 'ID del registro afectado',
  `datos` text DEFAULT NULL COMMENT 'Datos JSON del registro para auditor??a',
  `fecha_sync` datetime DEFAULT current_timestamp() COMMENT 'Fecha y hora de la sincronizaci??n',
  `origen` varchar(50) DEFAULT NULL COMMENT 'Origen: cron_nube, manual_local, api, etc',
  `hash_datos` varchar(64) DEFAULT NULL COMMENT 'Hash MD5 de los datos para detectar cambios',
  `sincronizado` tinyint(1) DEFAULT 0 COMMENT '1 si ya fue sincronizado al otro lado',
  `fecha_sincronizado` datetime DEFAULT NULL COMMENT 'Cu??ndo se sincroniz??'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Registro de sincronizaci??n entre BD local y nube';

